1	"use client";
2	
3	import { useEffect, useState } from "react";
4	import { installApp, installWordPress, listAppCatalog } from "@/lib/actions-hosting";
5	
6	/** One-click app installer dropdown (WordPress + catalog). Extracted verbatim
7	 *  from the old HostingClient; behaviour is identical. */
8	export function AppInstaller({ accountId }: { accountId: string }) {
9	  const [apps, setApps] = useState<{ slug: string; name: string; needsDb: boolean }[]>([]);
10	  const [busy, setBusy] = useState(false);
11	  useEffect(() => { listAppCatalog().then(setApps).catch(() => {}); }, []);
12	  async function pick(value: string) {
13	    if (!value) return;
14	    setBusy(true);
15	    const r = value === "wordpress" ? await installWordPress(accountId) : await installApp(accountId, value);
16	    setBusy(false);
17	    if (r.error) alert(r.error); else window.location.reload();
18	  }
19	  return (
20	    <label className="flex items-center gap-1.5 text-slate-400">
21	      Install app
22	      <select className="input py-1 text-xs" defaultValue="" disabled={busy} onChange={(e) => pick(e.target.value)}>
23	        <option value="">{busy ? "Installing…" : "choose…"}</option>
24	        <option value="wordpress">WordPress (auto)</option>
25	        {apps.map((ap) => (<option key={ap.slug} value={ap.slug}>{ap.name}</option>))}
26	      </select>
27	    </label>
28	  );
29	}
