1	"use client";
2	
3	import { useMemo, useRef, useState } from "react";
4	import { useActionState, useEffect } from "react";
5	import { payAndDeploy, previewOrderCoupon } from "@/lib/actions";
6	import { AppLogo } from "@/components/ui/AppLogo";
7	import { StripeCheckoutModal } from "@/components/customer/StripeCheckoutModal";
8	import { VersionPickerModal, type FamilyGroup } from "@/components/customer/VersionPickerModal";
9	// No vpsTermPriceCents here any more: every term price this wizard shows is now
10	// derived from lib/renewal-quote.ts (the regular/renewal rate) with the promo
11	// applied on top, so the file has exactly one source for what a term costs.
12	import { VPS_TERMS, vpsTerm, ANNUAL_TERM_MONTHS, DEFAULT_ANNUAL_DISCOUNT_PCT } from "@/lib/billing-terms";
13	import { renewalQuote } from "@/lib/renewal-quote";
14	import { walletSplit } from "@/lib/wallet-split";
15	import {
16	  EXTRA_DISK_MAX_ADD_GB,
17	  EXTRA_DISK_MIN_GB,
18	  EXTRA_DISK_ONE_WAY_NOTE,
19	  EXTRA_DISK_STEP_GB,
20	  effectiveDiskGB,
21	  extraDiskCentsAt,
22	} from "@/lib/extra-disk";
23	
24	type Plan = {
25	  id: string; name: string; cpuCores: number; ramMB: number; diskGB: number;
26	  bandwidthTB: number; priceCents: number; storageTier: string;
27	};
28	type Image = {
29	  id: string; slug: string; name: string; category: string; family: string;
30	  version: string; logo: string; minRamMB: number; minDiskGB: number;
31	  licenseRequired: boolean; featured: boolean;
32	};
33	type NodeOpt = { id: string; name: string; publicIp: string };
34	
35	const money = (c: number) => `$${(c / 100).toFixed(2)}`;
36	
37	/** sessionStorage key for the in-progress order — see the restore effect below. */
38	const DRAFT_KEY = "nxeon.deploy.draft.v1";
39	type Draft = {
40	  step: number;
41	  planId: string;
42	  nodeId: string;
43	  imageId: string;
44	  tab: string;
45	  addons: { malware: boolean; backup: boolean; docker: boolean };
46	  dedicatedIp: boolean;
47	  extraDiskGB: number;
48	  hostname: string;
49	  pubKey: string;
50	  termMonths: number;
51	  useWallet: boolean;
52	};
53	
54	/** APPLICATION-category images with one of these families are split into the Games tab. */
55	const GAME_FAMILIES = new Set(["minecraft", "valheim", "rust", "palworld", "cs2", "terraria"]);
56	
57	/** Install-step tabs. Games are peeled out of Applications into their own tab. */
58	const TABS = [
59	  { key: "os", label: "Operating Systems", match: (i: Image) => i.category === "PLAIN_OS" },
60	  { key: "panels", label: "Control Panels", match: (i: Image) => i.category === "CONTROL_PANEL" },
61	  { key: "apps", label: "Applications", match: (i: Image) => i.category === "APPLICATION" && !GAME_FAMILIES.has(i.family) },
62	  { key: "games", label: "Games", match: (i: Image) => i.category === "APPLICATION" && GAME_FAMILIES.has(i.family) },
63	] as const;
64	
65	const OS_FAMILY_NAMES: Record<string, string> = {
66	  ubuntu: "Ubuntu", debian: "Debian", almalinux: "AlmaLinux", rocky: "Rocky Linux",
67	  fedora: "Fedora", centos: "CentOS", arch: "Arch Linux", alpine: "Alpine", kali: "Kali Linux", opensuse: "openSUSE",
68	};
69	/**
70	 * Human name for an image on the confirmation screen.
71	 *
72	 * Catalogue rows carry the version in BOTH `name` ("Ubuntu 20.04") and `version`
73	 * ("20.04"), so appending unconditionally printed "Ubuntu 20.04 20.04" — on the
74	 * last screen before the customer pays. Only append a version the name does not
75	 * already end with.
76	 */
77	function imageLabel(img: Image) {
78	  const version = img.version?.trim();
79	  if (!version) return img.name;
80	  return img.name.trim().endsWith(version) ? img.name : `${img.name} ${version}`;
81	}
82	
83	/** Clean family display name (no version) for the OS family cards. */
84	function osFamilyName(img: Image) {
85	  return OS_FAMILY_NAMES[img.family] ?? img.name.replace(/\s+\d.*$/, "").trim() ?? img.family;
86	}
87	
88	function Stepper({ step, steps }: { step: number; steps: string[] }) {
89	  return (
90	    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
91	      {steps.map((s, i) => (
92	        <div key={s} className="flex items-center gap-2">
93	          <span
94	            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold ${
95	              i === step ? "border-brand-400 bg-brand-500/20 text-brand-200"
96	                : i < step ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
97	                  : "border-white/10 text-slate-500"
98	            }`}
99	          >
100	            {i < step ? "✓" : i + 1}
101	          </span>
102	          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
103	          {i < steps.length - 1 && <span className="mx-1 text-slate-700">→</span>}
104	        </div>
105	      ))}
106	    </div>
107	  );
108	}
109	
110	export function DeployWizard({
111	  plans, images, nodes, sshKeys, isAdmin, balanceCents, dedicatedIpAvailable, dedicatedIpPriceCents,
112	  extraDiskPriceCentsPerGb = 0,
113	  backupPlusPriceCents = 0,
114	  defaultPlanId, defaultTermMonths,
115	  promoPercent = 0, promoLabel,
116	  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
117	  taxRatePercent = 0, taxCountry = "",
118	}: {
119	  plans: Plan[]; images: Image[]; nodes: NodeOpt[];
120	  sshKeys: { id: string; name: string }[]; isAdmin: boolean; balanceCents: number;
121	  dedicatedIpAvailable?: boolean; dedicatedIpPriceCents?: number;
122	  /**
123	   * Price per GB per month for extra ROOT DISK (admin setting
124	   * `extra_disk_gb_price_cents`). Priced over the term exactly like the dedicated
125	   * IP add-on, so the maths here matches lib/order.ts orderQuote byte-for-byte.
126	   * 0 hides the upsell entirely.
127	   */
128	  extraDiskPriceCentsPerGb?: number;
129	  /**
130	   * Monthly price of the Plus backup-retention tier (admin setting
131	   * `backup_plus_price_cents`). Priced over the term like the other add-ons so this
132	   * matches lib/order.ts orderQuote byte-for-byte.
133	   */
134	  backupPlusPriceCents?: number;
135	  /**
136	   * Plan pre-selected on step 1, from the `default_plan_slug` admin setting.
137	   *
138	   * An **id**, not the slug the setting stores: this component's `Plan` type carries no
139	   * slug, so matching here would mean widening the payload or matching on `name`. The
140	   * page resolves slug → id against the very array it passes down, so any id arriving
141	   * here is guaranteed to be in `plans`; a stale slug (plan renamed, or deactivated)
142	   * arrives as `undefined` and the wizard falls back to the first plan rather than
143	   * opening with nothing selected and no price on the Review step.
144	   */
145	  defaultPlanId?: string;
146	  /**
147	   * Billing term pre-selected on the Review step, in MONTHS, from `default_term`.
148	   *
149	   * Guaranteed by `defaultTermMonths()` to be one of `VPS_TERMS`. That guarantee is
150	   * load-bearing: the term buttons below are rendered straight from `VPS_TERMS` and
151	   * highlight on `termMonths === t.months`, so an unlisted value (the old setting's
152	   * "quarterly", say) would render a Review step with no term highlighted while the
153	   * hidden `termMonths` field still posted it — and `vpsTerm()` silently falls back to
154	   * monthly, so the customer would be charged for a term nothing on screen showed.
155	   */
156	  defaultTermMonths?: number;
157	  /** Active intro-promo discount (%) on the FIRST term — matches what payAndDeploy charges. */
158	  promoPercent?: number; promoLabel?: string;
159	  /**
160	   * The admin ANNUAL discount (`annual_discount_percent`), resolved server-side and
161	   * passed in so the Annual term card's price, savings and `−X%` badge are the REAL
162	   * configured rate — the same one lib/order.ts charges and renewalCharge renews at.
163	   * Threaded into `renewalQuote` below so displayed === charged === renewed. Only
164	   * affects the 12-month card; every other term keeps its fixed rate.
165	   */
166	  annualDiscountPct?: number;
167	  /**
168	   * Destination VAT/GST rate (%) for THIS customer's billing country (Finding 1),
169	   * resolved server-side (lib/tax.ts taxContextForUser). 0 (the default, and the case
170	   * for any customer with no billing country on file) adds no tax and leaves the total
171	   * exactly as before. When > 0 the summary shows a tax line and `dueCents` is made
172	   * tax-inclusive, so what is shown here === what payAndDeploy charges.
173	   */
174	  taxRatePercent?: number;
175	  taxCountry?: string;
176	}) {
177	  const [state, action, pending] = useActionState(
178	    payAndDeploy,
179	    {} as { error?: string; checkout?: { clientSecret: string; publishableKey: string } },
180	  );
181	  // The embedded Stripe session to mount in a modal on THIS page (no redirect),
182	  // set only on an explicit Deploy submit (see submittedRef below).
183	  const [checkoutSession, setCheckoutSession] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
184	  // Apply the first-term promo to any regular price, mirroring promoPriceCents()
185	  // in lib/promotions.ts so the wizard's displayed price === the checkout charge.
186	  const hasPromo = promoPercent > 0;
187	  const promoCents = (regular: number) => Math.round(regular * (1 - promoPercent / 100));
188	  // Only redirect to Stripe as the result of an EXPLICIT Deploy submit. The flag is
189	  // armed in the Deploy button's onClick (and the Enter-on-final-step path) and
190	  // consumed here, so a stale `checkoutUrl` in state can never redirect on its own —
191	  // e.g. after a back-button remount (ref starts false) or an unrelated re-render.
192	  const submittedRef = useRef(false);
193	  useEffect(() => {
194	    if (state?.checkout && submittedRef.current) {
195	      submittedRef.current = false;
196	      // The "vps" conversion is fired at FULFILMENT (PurchaseTracker, with the real
197	      // charged value + transaction_id) — NOT here at checkout-start, which would
198	      // count customers who abandon at the payment step.
199	      setCheckoutSession(state.checkout);
200	    }
201	    // `dueCents` is derived state read only inside the fire-and-forget tracking call;
202	    // opening the modal depends only on `state`.
203	    // eslint-disable-next-line react-hooks/exhaustive-deps
204	  }, [state]);
205	  const multiNode = nodes.length > 1;
206	  const steps = ["Plan", ...(multiNode ? ["Location"] : []), "Install", "Add-ons", "Access", "Review"];
207	  const [step, setStep] = useState(0);
208	
209	  const [planId, setPlanId] = useState(defaultPlanId ?? plans[0]?.id ?? "");
210	  const [nodeId, setNodeId] = useState(nodes[0]?.id ?? "");
211	  const [imageId, setImageId] = useState(images.find((i) => i.category === "PLAIN_OS")?.id ?? images[0]?.id ?? "");
212	  const [tab, setTab] = useState<string>("os");
213	  const [modalFamily, setModalFamily] = useState<string | null>(null);
214	  const [q, setQ] = useState("");
215	  const [addons, setAddons] = useState({ malware: false, backup: false, docker: false });
216	  const [dedicatedIp, setDedicatedIp] = useState(false);
217	  // Backup RETENTION tier: "FREE" (keep 2, included) or "PLUS" (keep 7, paid).
218	  const [backupTier, setBackupTier] = useState<"FREE" | "PLUS">("FREE");
219	  // Extra ROOT DISK bought up front. One-way: this space can never be removed
220	  // later, which the Add-ons card and the Review step both state before payment.
221	  const [extraDiskGB, setExtraDiskGB] = useState(0);
222	  const [hostname, setHostname] = useState("");
223	  const [pubKey, setPubKey] = useState("");
224	  const [free, setFree] = useState(false);
225	  const [termMonths, setTermMonths] = useState(defaultTermMonths ?? VPS_TERMS[0].months);
226	  // Apply the wallet balance by default whenever there's something to apply.
227	  const [useWallet, setUseWallet] = useState(balanceCents > 0);
228	  // Checkout promo code. `couponApplied` holds the server-verified discount so the
229	  // displayed total matches what placeOrder charges; it is cleared whenever the
230	  // selection changes (a "Starter only" code stops applying if they switch plans).
231	  const [couponInput, setCouponInput] = useState("");
232	  const [couponApplied, setCouponApplied] = useState<{ code: string; label: string; discountCents: number } | null>(null);
233	  const [couponMsg, setCouponMsg] = useState("");
234	  const [couponBusy, setCouponBusy] = useState(false);
235	  // Set when we come back from a cancelled Stripe Checkout, so the banner can
236	  // say what happened instead of leaving the customer on a silently reset form.
237	  const [restoredAfterCancel, setRestoredAfterCancel] = useState(false);
238	
239	  /**
240	   * Keep the customer's choices alive across the Stripe round-trip.
241	   *
242	   * Cancelling on Stripe's page hard-navigates back to
243	   * `/dashboard/deploy?canceled=1`, which remounts this component from scratch:
244	   * plan, image, add-ons, disk slider, hostname and term all gone. `?canceled=1`
245	   * was read by nothing, so there was no explanation either — the customer just
246	   * found an empty wizard and had to guess whether they had been charged.
247	   *
248	   * sessionStorage is per-tab and survives that navigation where `useState`
249	   * cannot. The draft is written on every change and read back ONLY on a
250	   * `?canceled=1` return, then deleted — a draft that reappeared on some later
251	   * visit would be its own surprise.
252	   *
253	   * No root password is drafted or submitted: provisioning always generates one
254	   * server-side and shows it on the server page. There is no field to preserve.
255	   */
256	  useEffect(() => {
257	    let canceled = false;
258	    try {
259	      canceled = new URLSearchParams(window.location.search).get("canceled") === "1";
260	    } catch {
261	      /* no URL access — fall through as a normal mount */
262	    }
263	    if (!canceled) return;
264	    let d: Draft | null = null;
265	    try {
266	      const raw = sessionStorage.getItem(DRAFT_KEY);
267	      sessionStorage.removeItem(DRAFT_KEY);
268	      if (raw) d = JSON.parse(raw) as Draft;
269	    } catch {
270	      d = null;
271	    }
272	    setRestoredAfterCancel(true);
273	    if (!d) return;
274	    // Every id is re-checked against the props actually rendered: a plan can be
275	    // deactivated or an image retired while the customer is on Stripe's page, and
276	    // selecting an id that is no longer in the list would show a blank Review
277	    // step with no price on it.
278	    if (plans.some((p) => p.id === d.planId)) setPlanId(d.planId);
279	    if (nodes.some((n) => n.id === d.nodeId)) setNodeId(d.nodeId);
280	    if (images.some((i) => i.id === d.imageId)) setImageId(d.imageId);
281	    if (TABS.some((t) => t.key === d.tab)) setTab(d.tab);
282	    if (d.addons) setAddons({ malware: !!d.addons.malware, backup: !!d.addons.backup, docker: !!d.addons.docker });
283	    setDedicatedIp(!!d.dedicatedIp);
284	    if (Number.isFinite(d.extraDiskGB)) setExtraDiskGB(d.extraDiskGB);
285	    if (typeof d.hostname === "string") setHostname(d.hostname);
286	    if (typeof d.pubKey === "string") setPubKey(d.pubKey);
287	    if (VPS_TERMS.some((t) => t.months === d.termMonths)) setTermMonths(d.termMonths);
288	    setUseWallet(!!d.useWallet && balanceCents > 0);
289	    if (Number.isInteger(d.step) && d.step >= 0 && d.step < steps.length) setStep(d.step);
290	    // Mount-only: this restores a one-shot draft and must never re-run.
291	    // eslint-disable-next-line react-hooks/exhaustive-deps
292	  }, []);
293	
294	  useEffect(() => {
295	    try {
296	      const draft: Draft = {
297	        step, planId, nodeId, imageId, tab, addons, dedicatedIp,
298	        extraDiskGB, hostname, pubKey, termMonths, useWallet,
299	      };
300	      sessionStorage.setItem(DRAFT_KEY, JSON.stringify(draft));
301	    } catch {
302	      /* storage disabled or full — the wizard still works, it just cannot
303	         survive the Stripe round-trip. Never break the order over this. */
304	    }
305	  }, [step, planId, nodeId, imageId, tab, addons, dedicatedIp, extraDiskGB, hostname, pubKey, termMonths, useWallet]);
306	
307	  const plan = plans.find((p) => p.id === planId);
308	  const image = images.find((i) => i.id === imageId);
309	
310	  const activeTab = TABS.find((t) => t.key === tab) ?? TABS[0];
311	
312	  // Images in the active tab, filtered by search.
313	  const tabImages = useMemo(() => {
314	    const needle = q.trim().toLowerCase();
315	    return images.filter(
316	      (i) => activeTab.match(i) && (needle === "" || (i.name + " " + i.version).toLowerCase().includes(needle)),
317	    );
318	  }, [images, activeTab, q]);
319	
320	  // OS tab: group images into one card per family (each with its versions).
321	  const osFamilies = useMemo<FamilyGroup[]>(() => {
322	    const map = new Map<string, FamilyGroup>();
323	    for (const i of tabImages) {
324	      const g = map.get(i.family) ?? { family: i.family, name: osFamilyName(i), logo: i.logo, versions: [] };
325	      g.versions.push(i);
326	      map.set(i.family, g);
327	    }
328	    for (const g of map.values()) g.versions.sort((a, b) => b.version.localeCompare(a.version, undefined, { numeric: true }));
329	    return [...map.values()];
330	  }, [tabImages]);
331	
332	  const openFamily = (g: FamilyGroup) => {
333	    if (g.versions.length === 1) setImageId(g.versions[0].id);
334	    else setModalFamily(g.family);
335	  };
336	  const modalGroup = modalFamily ? osFamilies.find((g) => g.family === modalFamily) : undefined;
337	
338	  const hostnameValid = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i.test(hostname) && hostname.length >= 3;
339	  const planMeetsImage = !!plan && !!image && plan.ramMB >= image.minRamMB && plan.diskGB >= image.minDiskGB;
340	  const ipMonthly = dedicatedIp ? dedicatedIpPriceCents ?? 0 : 0;
341	  // Extra root disk: per-GB/month × GB, then × the term — priced exactly like the
342	  // dedicated IP (no term discount, no promo), matching lib/order.ts orderQuote.
343	  const extraDiskOffered = (extraDiskPriceCentsPerGb ?? 0) > 0;
344	  const extraDiskMonthly = extraDiskCentsAt(extraDiskGB, extraDiskPriceCentsPerGb ?? 0);
345	  const totalDiskGB = plan ? effectiveDiskGB(plan.diskGB, extraDiskGB) : 0;
346	  // Paid backup retention: Plus is a flat monthly add-on (no term discount, no
347	  // promo), priced over the term exactly like extra disk / dedicated IP.
348	  const backupUpsellOffered = (backupPlusPriceCents ?? 0) > 0;
349	  const backupMonthly = backupTier === "PLUS" ? backupPlusPriceCents ?? 0 : 0;
350	
351	  /**
352	   * What a term costs at the REGULAR rate — i.e. what a renewal of it will bill.
353	   * ONE definition, shared with the "Renew now" button on the server page and with
354	   * the action that charges it: `lib/renewal-quote.ts`.
355	   *
356	   * REAL INCIDENT (2026-07-26 rehearsal, H1): the term cards derived this
357	   * themselves and then printed the PROMO first-term total against the words
358	   * "billed every 1 yr" — "$67.96 billed every 1 yr" on a term that renews at
359	   * $97.09. `currentPromo()` never returns null (lib/promotions.ts always has an
360	   * active sale), so the recurring figure on those cards was wrong on 100% of
361	   * orders. Renewals bill the regular price with no promo — promos are first-term
362	   * introductory offers — and they DO bill the add-ons, so this is the whole
363	   * basket at the regular rate, exactly as worker/billing.ts will charge it.
364	   */
365	  // `gamePlan: null` is correct and not an oversight: this wizard sells plain VPS
366	  // plans. Game servers are ordered through their own flow (lib/actions-gameplans.ts)
367	  // at a flat all-in price and never reach these term cards.
368	  const regularTermCents = (months: number) =>
369	    plan
370	      ? renewalQuote(
371	          {
372	            termMonths: months,
373	            extraDiskGB: extraDiskGB,
374	            plan: { name: plan.name, priceCents: plan.priceCents },
375	            gamePlan: null,
376	            dedicatedIp: dedicatedIp ? {} : null,
377	            backupTier: "FREE",
378	          },
379	          {
380	            ipMonthlyCents: dedicatedIpPriceCents ?? 0,
381	            extraDiskPerGbCents: extraDiskPriceCentsPerGb ?? 0,
382	            // The backup add-on is priced separately via addonTermCentsFor below,
383	            // so the plan term card prices FREE here to avoid double-counting.
384	            backupPlusCents: 0,
385	            // The Annual card prices against the LIVE admin discount, so what the
386	            // card shows for the 12-month term is exactly what checkout charges and
387	            // the renewal sweep bills.
388	            annualDiscountPct,
389	          },
390	        ).totalCents
391	      : 0;
392	  /**
393	   * Effective per-month price of ANY plan at a given term — the plan's term total
394	   * (no add-ons) divided by the months. Priced through the SAME renewalQuote formula
395	   * checkout and the renewal sweep use, so the "/mo" shown on the Plan step === what is
396	   * charged. Used to make the Plan-step cards reflect the term the customer picks, so a
397	   * longer commitment visibly lowers the monthly number right where they choose the plan.
398	   */
399	  const planMonthlyAtTerm = (planPriceCents: number, months: number) =>
400	    Math.round(
401	      renewalQuote(
402	        {
403	          termMonths: months,
404	          extraDiskGB: 0,
405	          plan: { name: "", priceCents: planPriceCents },
406	          gamePlan: null,
407	          dedicatedIp: null,
408	          backupTier: "FREE",
409	        },
410	        { ipMonthlyCents: 0, extraDiskPerGbCents: 0, backupPlusCents: 0, annualDiscountPct },
411	      ).netCents / Math.max(1, months),
412	    );
413	  /** Add-on portion of a term. Never promo-discounted, in the wizard or in checkout. */
414	  const addonTermCentsFor = (months: number) => (ipMonthly + extraDiskMonthly + backupMonthly) * months;
415	  /**
416	   * What the FIRST term costs — the promo applied to the plan portion only, then
