255	/**
256	 * DNS→HTTPS stepper driven by the REAL serve-verification the worker records
257	 * (serveHttpOk / serveHttpsOk / sslActive), so it can never claim "live" while
258	 * HTTPS actually refuses. Three overall states, per the account's measured health:
259	 *   • verified — a trusted cert is live (sslActive) and 443 answers → "HTTPS live ✓"
260	 *   • issuing  — the site answers (self-signed 443 or HTTP) but no trusted cert yet
261	 *   • dns      — nothing answers for the domain yet (DNS not pointed at us)
262	 */
263	function DnsStepper({ account }: { account: HostingAccountView }) {
264	  const checked = account.healthCheckedAt != null || account.serveHttpOk != null;
265	  const serving = account.serveHttpOk === true || account.serveHttpsOk === true;
266	  const verified = account.sslActive && account.serveHttpsOk !== false;
267	  const state: "verified" | "issuing" | "dns" | "pending" =
268	    verified ? "verified" : serving ? "issuing" : checked ? "dns" : "pending";
269	
270	  const free = account.isFreeSubdomain;
271	  const steps = [
272	    { label: free ? "DNS ready" : "Point domain", done: true, hint: free ? "Set up automatically" : "Add the A record above" },
273	    {
274	      label: "Site live",
275	      done: state === "issuing" || state === "verified",
276	      hint: state === "issuing" || state === "verified" ? "Serving traffic" : state === "dns" ? "DNS not detected yet" : "Checking…",
277	    },
278	    {
279	      label: "HTTPS verified",
280	      done: state === "verified",
281	      hint: state === "verified" ? "Certificate trusted" : state === "issuing" ? "Issuing certificate" : "Auto after DNS",
282	    },
283	  ];
284	
285	  const headline =
286	    account.healthNote ??
287	    (state === "verified" ? "HTTPS live — verified" : state === "issuing" ? "HTTP live, HTTPS issuing" : state === "dns" ? "DNS not detected yet" : "Not checked yet");
288	  const headlineTone = state === "verified" ? "text-emerald-300" : state === "dns" ? "text-slate-400" : "text-amber-300";
289	
290	  return (
291	    <div className="mt-4">
292	      <div className="flex items-center">
293	        {steps.map((s, i) => (
294	          <div key={s.label} className="flex flex-1 items-center last:flex-none">
295	            <div className="flex flex-col items-center">
296	              <span className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] ${s.done ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300" : "border-amber-500/40 bg-amber-500/10 text-amber-300"}`}>
297	                {s.done ? "✓" : i + 1}
298	              </span>
299	            </div>
300	            {i < steps.length - 1 && <div className={`mx-2 h-px flex-1 ${steps[i + 1].done ? "bg-emerald-500/40" : "bg-white/10"}`} />}
301	          </div>
302	        ))}
303	      </div>
304	      <div className="mt-1.5 flex items-start justify-between text-[11px]">
305	        {steps.map((s) => (
306	          <div key={s.label} className="flex-1 text-center first:text-left last:text-right">
307	            <p className={s.done ? "text-emerald-300" : "text-slate-400"}>{s.label}</p>
308	            <p className="text-slate-500">{s.hint}</p>
309	          </div>
310	        ))}
311	      </div>
312	      <p className={`mt-3 text-xs font-medium ${headlineTone}`}>
313	        {headline}
314	        {account.healthCheckedAt && (
315	          <span className="ml-1 font-normal text-slate-500">· checked {new Date(account.healthCheckedAt).toLocaleTimeString()}</span>
316	        )}
317	      </p>
318	      {state !== "verified" && (
319	        <p className="mt-1 text-xs text-slate-500">
320	          {free ? (
321	            <>A trusted HTTPS certificate is issued automatically once provisioning completes — this usually takes a minute. Use <span className="text-slate-300">Refresh</span> to check right away.</>
322	          ) : (
323	            <>A trusted HTTPS certificate is issued automatically once your domain resolves to us — this can take a few minutes after you set the DNS record. Use <span className="text-slate-300">Go live</span> to check right away.</>
324	          )}
325	        </p>
326	      )}
327	    </div>
328	  );
329	}
