18	export type HostingAppMenuItem = {
19	  slug: string;
20	  name: string;
21	  needsDb: boolean;
22	  blurb: string;
23	  /** Simple Icons SVG path (24×24 viewBox), or undefined for a fallback initial tile. */
24	  logoPath?: string;
