26	  logoHex?: string;
27	};
28	
29	// slug → Simple Icons export key (`si<Brand>`). Unknown/removed keys resolve to
30	// undefined and fall through to the initial-tile fallback, so an optimistic key is
31	// always safe. phpbb + grav have no Simple Icons brand mark → intentionally absent.
32	const SI_KEY: Record<string, string> = {
33	  wordpress: "siWordpress",
34	  joomla: "siJoomla",
35	  drupal: "siDrupal",
36	  matomo: "siMatomo",
37	  nextcloud: "siNextcloud",
38	  mediawiki: "siMediawiki",
39	  prestashop: "siPrestashop",
40	  moodle: "siMoodle",
41	  // No Simple Icons brand mark — these use the initial-tile fallback: phpbb, grav
42	};
43	
44	// A short human blurb per app for the wizard card. A slug with no entry falls back
45	// to a generic database/no-database line (keeps a newly-added recipe from breaking).
46	const BLURBS: Record<string, string> = {
47	  wordpress: "The world’s most popular CMS — installed and configured for you.",
48	  joomla: "Flexible open-source CMS for portals and complex sites.",
49	  drupal: "Enterprise-grade CMS for structured, high-volume content.",
50	  phpbb: "The classic open-source community forum.",
51	  matomo: "Privacy-friendly, self-hosted web analytics.",
52	  grav: "Fast flat-file CMS — no database needed.",
53	  nextcloud: "Your own private cloud for files, calendars and contacts.",
54	  mediawiki: "The wiki engine that powers Wikipedia.",
55	  prestashop: "Full-featured open-source e-commerce platform.",
56	  moodle: "The open-source learning management system.",
57	};
