59	type SimpleIcon = { path?: string; hex?: string };
60	
61	/** Resolve a Simple Icons glyph for a slug, or {} when the brand isn't carried. */
62	function resolveLogo(slug: string): { logoPath?: string; logoHex?: string } {
63	  const key = SI_KEY[slug];
64	  if (!key) return {};
65	  const icon = (simpleIcons as Record<string, unknown>)[key] as SimpleIcon | undefined;
66	  if (icon && typeof icon.path === "string") {
67	    return { logoPath: icon.path, logoHex: typeof icon.hex === "string" ? icon.hex : undefined };
68	  }
69	  return {};
70	}
