72	/** The ordered one-click install menu for the deploy wizard. WordPress first, then
73	 *  every recipe app the worker supports, each enriched with a blurb + logo. */
74	export function hostingAppMenu(): HostingAppMenuItem[] {
75	  const items: HostingAppMenuItem[] = [
76	    // WordPress FIRST — fully automated via its own WORDPRESS_INSTALL task, so it is
77	    // not part of hostingAppCatalog(); prepend it here.
78	    { slug: "wordpress", name: "WordPress", needsDb: true, blurb: BLURBS.wordpress, ...resolveLogo("wordpress") },
