/**
 * The enriched one-click install menu for the Apps tab: WordPress first (installed
 * via its own automated WORDPRESS_INSTALL task), then every catalog recipe the
 * worker supports — each with a short blurb and, where available, a Simple Icons
 * brand-glyph path so the tile can render a real logo. `simple-icons` is resolved
 * here (server-only); only the pre-extracted SVG path string crosses to the client.
 */
export async function listHostingAppMenu(): Promise<HostingAppMenuItem[]> {
  await requireUser();
  return hostingAppMenu();
}

