"use client";

import { useEffect, useState } from "react";
import { installApp, installWordPress, listHostingAppMenu, listHostingTasks } from "@/lib/actions-hosting";
import { AppLogo } from "@/components/ui/AppLogo";

/** One enriched catalog entry as returned by listHostingAppMenu(). */
type AppItem = {
  slug: string;
  name: string;
  needsDb: boolean;
  blurb: string;
  /** Simple Icons SVG path (24×24 viewBox) — undefined falls back to AppLogo. */
  logoPath?: string;
  /** Brand hex WITHOUT the leading '#', or undefined. */
  logoHex?: string;
};

type Task = { id: string; kind: string; status: string; result: string | null; error: string | null; createdAt: string };

function safeJson(s: string | null): any {
  if (!s) return null;
  try { return JSON.parse(s); } catch { return null; }
}

/**
 * App tile logo. Prefers the Simple Icons brand glyph (rendered inline on a light
 * chip so both light and dark marks read on the dark UI), and falls back to the
 * shared AppLogo — which itself resolves a bundled /public/logos SVG or a tasteful
 * lettermark, mirroring the deploy-wizard convention. Never blank.
 */
function AppTileLogo({ slug, name, logoPath, logoHex, size = 40 }: {
  slug: string; name: string; logoPath?: string; logoHex?: string; size?: number;
}) {
  if (logoPath) {
    return (
      <span
        className="flex items-center justify-center rounded-lg border border-white/10 bg-white/90 p-1.5"
        style={{ width: size, height: size, minWidth: size }}
      >
        <svg viewBox="0 0 24 24" className="h-full w-full" role="img" aria-label={`${name} logo`}>
          <path d={logoPath} fill={logoHex ? `#${logoHex}` : "#0f172a"} />
        </svg>
      </span>
    );
  }
  return <AppLogo family={slug} name={name} size={size} />;
}

const STATUS_TONE: Record<string, string> = {
  DONE: "border-emerald-500/30 bg-emerald-500/10 text-emerald-200",
  FAILED: "border-red-500/30 bg-red-500/10 text-red-200",
};
const statusLabel = (s: string) =>
  s === "PENDING" ? "Queued" : s === "RUNNING" ? "Installing…" : s === "DONE" ? "Installed" : s === "FAILED" ? "Failed" : s.toLowerCase();

/**
 * One-click app installer — a responsive grid of app logo tiles (WordPress first,
 * then the full catalog), styled like the VPS deploy wizard's OS picker. Selecting
 * a tile reveals an Install action; the install is enqueued as a hosting task and
 * the panel surfaces immediate, honest feedback: an "installing…" state, a live
 * queue below (so a SANDBOX/non-prod account still shows the queued/active task),
 * and, when the worker finishes, the resulting site + admin login. All security
 * lives in the server actions (ownership, DB caps, cross-tenant) — this is UI only.
 */
export function AppInstaller({ accountId }: { accountId: string }) {
  const [apps, setApps] = useState<AppItem[]>([]);
  const [selected, setSelected] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [tasks, setTasks] = useState<Task[]>([]);

  useEffect(() => { listHostingAppMenu().then(setApps).catch(() => {}); }, []);

  // Live view of this account's install tasks so a queued/running install is always
  // visible from the Apps tab itself (not only the Overview feed), including while a
  // SANDBOX/non-prod worker leaves it PENDING.
  useEffect(() => {
    let stop = false;
    const load = () =>
      listHostingTasks(accountId)
        .then((t) => { if (!stop) setTasks(t.filter((x) => x.kind === "WORDPRESS_INSTALL" || x.kind === "APP_INSTALL")); })
        .catch(() => {});
    load();
    const timer = setInterval(load, 5000);
    return () => { stop = true; clearInterval(timer); };
  }, [accountId]);

  const chosen = apps.find((a) => a.slug === selected) ?? null;

  async function install(slug: string) {
    setBusy(true);
    setError(null);
    setNotice(null);
    try {
      const r = slug === "wordpress" ? await installWordPress(accountId) : await installApp(accountId, slug);
      if (r.error) {
        setError(r.error);
      } else {
        const name = apps.find((a) => a.slug === slug)?.name ?? "App";
        setNotice(`${name} is being installed — track its progress below. This usually takes a minute.`);
        setSelected(null);
        // Refresh the queue immediately so the new task appears without waiting for the poll.
        listHostingTasks(accountId)
          .then((t) => setTasks(t.filter((x) => x.kind === "WORDPRESS_INSTALL" || x.kind === "APP_INSTALL")))
          .catch(() => {});
      }
    } catch {
      setError("Something went wrong starting that install. Please try again.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="space-y-4">
      {error && (
        <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{error}</div>
      )}
      {notice && (
        <div className="rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-200">{notice}</div>
      )}

      <div className="grid gap-2.5 sm:grid-cols-2 lg:grid-cols-3">
        {apps.map((ap) => {
          const active = selected === ap.slug;
          const featured = ap.slug === "wordpress";
          return (
            <button
              type="button"
              key={ap.slug}
              onClick={() => { setSelected(active ? null : ap.slug); setError(null); }}
              disabled={busy}
              aria-pressed={active}
              className={`card relative flex items-start gap-3 !p-3 text-left transition disabled:opacity-60 ${
                active ? "!border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"
              }`}
            >
              {featured && (
                <span className="absolute -top-2 right-2 rounded-full bg-gradient-to-r from-accent-blue to-brand-500 px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-wider text-white shadow">
                  Recommended
                </span>
              )}
              <AppTileLogo slug={ap.slug} name={ap.name} logoPath={ap.logoPath} logoHex={ap.logoHex} />
              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-2">
                  <span className="truncate text-sm font-semibold">{ap.name}</span>
                  {ap.needsDb ? (
                    <span className="shrink-0 rounded bg-brand-500/15 px-1.5 py-0.5 text-[10px] text-brand-200">database</span>
                  ) : (
                    <span className="shrink-0 rounded bg-emerald-500/15 px-1.5 py-0.5 text-[10px] text-emerald-300">no DB</span>
                  )}
                </div>
                <p className="mt-0.5 line-clamp-2 text-[11px] leading-snug text-slate-400">{ap.blurb}</p>
              </div>
              <span className={`mt-0.5 h-4 w-4 shrink-0 rounded-full border ${active ? "border-brand-400 bg-brand-500" : "border-white/20"}`} aria-hidden />
            </button>
          );
        })}
        {apps.length === 0 && <p className="col-span-full text-sm text-slate-500">Loading apps…</p>}
      </div>

      {chosen && (
        <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-brand-400/40 bg-brand-500/[0.06] px-4 py-3">
          <div className="flex items-center gap-3">
            <AppTileLogo slug={chosen.slug} name={chosen.name} logoPath={chosen.logoPath} logoHex={chosen.logoHex} size={32} />
            <div>
              <p className="text-sm font-semibold">{chosen.name}</p>
              <p className="text-[11px] text-slate-400">
                {chosen.needsDb ? "A database will be created for you." : "No database needed."}
              </p>
            </div>
          </div>
          <button type="button" className="btn-primary px-3 py-1.5 text-sm" disabled={busy} onClick={() => install(chosen.slug)}>
            {busy ? "Installing…" : `Install ${chosen.name}`}
          </button>
        </div>
      )}

      {tasks.length > 0 && (
        <div className="space-y-2">
          <h4 className="text-xs font-semibold uppercase tracking-wide text-slate-500">Installations</h4>
          {tasks.map((t) => {
            const isWp = t.kind === "WORDPRESS_INSTALL";
            const result = t.status === "DONE" ? safeJson(t.result) : null;
            const name = isWp ? "WordPress" : result?.app ?? "App";
            const done = t.status === "DONE";
            return (
              <div
                key={t.id}
                className={`rounded-lg border px-3 py-2 text-sm ${STATUS_TONE[t.status] ?? "border-amber-500/30 bg-amber-500/10 text-amber-200"}`}
              >
                <div className="flex items-center justify-between gap-2">
                  <span className="font-medium">{name}</span>
                  <span className="text-xs">{statusLabel(t.status)}</span>
                </div>
                {t.error && <p className="mt-1 text-xs opacity-90">{t.error}</p>}
                {done && isWp && result?.url && (
                  <p className="mt-1 text-xs opacity-90">
                    Log in at <a href={result.url} target="_blank" rel="noreferrer" className="font-mono underline">{result.url}</a> · user{" "}
                    <span className="font-mono">{result.adminUser}</span> · password <span className="font-mono">{result.adminPassword}</span>{" "}
                    <span className="opacity-80">(also saved under App credentials)</span>
                  </p>
                )}
                {done && !isWp && result?.note && <p className="mt-1 text-xs opacity-90">{result.note}</p>}
                {!done && t.status !== "FAILED" && (
                  <p className="mt-1 text-xs opacity-90">We’re setting this up — this panel and your Overview update automatically.</p>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
